"""Curated offline prompt presets and timeline direction recommendations."""

from __future__ import annotations


def _presets(rows: tuple[tuple[str, str], ...]) -> dict[str, str]:
    if len(rows) != 32:
        raise ValueError(f"A preset family must contain exactly 32 entries, got {len(rows)}")
    return dict(rows)


